import sys
import math

def main():
    n = int(sys.argv[1])

    size = 1000  # standard benchmark size; spectral norm problem uses this fixed matrix size

    def A(i, j):
        s = i + j
        return 1.0 / (((s * (s + 1)) // 2) + i + 1)

    u = [1.0] * size
    v = [0.0] * size

    for _ in range(n):
        # v = A * u
        for i in range(size):
            ai = 0.0
            for j in range(size):
                ai += A(i, j) * u[j]
            v[i] = ai

        # u = A^T * v
        for i in range(size):
            ai = 0.0
            for j in range(size):
                ai += A(j, i) * v[j]
            u[i] = ai

    vBv = 0.0
    vv = 0.0
    for i in range(size):
        vBv += u[i] * v[i]
        vv += v[i] * v[i]

    print(f"{math.sqrt(vBv / vv):.9f}")

if __name__ == "__main__":
    main()
